local OverseaManageMerchantFriendCell = Class('OverseaManageMerchantFriendCell')
local FontStyleButton = CS.Game.Native.Common.FontStyleButton
---@type MaidCoffeeConstants
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local TabType = {
    Friend = 1,
    Record = 2,
}
function OverseaManageMerchantFriendCell:__init()

end

function OverseaManageMerchantFriendCell:__delete()

end

function OverseaManageMerchantFriendCell:Awake()
    self.playerHeadEnv_ = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, Constants.UILuaTablePath.ComPlayerHead)
    SetButtonAction(self.FontStyleWithIconButton.gameObject,Bind(self,self.OnBtnCallOnClick))

    SetButtonAction(self.FontStyleButton1.gameObject,Bind(self,self.OnBtnCallOnClick))
    SetButtonAction(self.FontStyleButton2.gameObject,Bind(self,self.OnBtnApplyFriendClick))
end

function OverseaManageMerchantFriendCell:SetClickCB(cb)
    self.callBack = cb
end

function OverseaManageMerchantFriendCell:SetLuaIndexAndData(index,data,type)
    self.index = index
    self.data = data
    self.type = type
    self:RefreshCellShow()
end

function OverseaManageMerchantFriendCell:RefreshCellShow()
    self:SetCommonShow()
    KTool.SetActive(self.ButtonGroup1.gameObject,self.type == TabType.Friend)
    KTool.SetActive(self.ButtonGroup2.gameObject,self.type == TabType.Record)
    KTool.SetActive(self.RelationalTag.gameObject,self.type == TabType.Record)
    KTool.SetActive(self.TxtTime.gameObject,self.type == TabType.Record)
    KTool.SetActive(self.TxtState.gameObject,self.type == TabType.Record)
    KTool.SetActive(self.TxtLevel.gameObject,self.type == TabType.Friend)
    if self.type == TabType.Friend then
        local isNotOpen = self:IsNotOpen()
        KTool.SetActive(self.TxtUnOpen.gameObject,isNotOpen)
        KTool.SetActive(self.FontStyleWithIconButton.gameObject,not isNotOpen)
        if isNotOpen then
            KTool.SetActive(self.AverageRate.gameObject,false)
        else
            if isNull(self.data.merchant) or not next(self.data.merchant) then
                KTool.SetActive(self.AverageRate.gameObject,false)
            else
                KTool.SetActive(self.AverageRate.gameObject,true)
                local path = CS.ParseUtils.ParsePathNameByData(self.data.merchant.icon)
                CfUtils.FillImage(self.ImgHeadIcon.gameObject,path)
                local goodIdVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 54)
                local goodsId = checkNumber(goodIdVo.num)
                if goodsId then
                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                    if not isNull(goodsVo) then
                        CfUtils.FillImage(self.ImgIcon,goodsVo.photoPath)
                    end
                end
                KTool.SetActive(self.UIFX_Perfect.gameObject,self.data.merchant.goodsQuality == 3)
                CfUtils.SetUISwitchImage(self.ChatBg,self.data.merchant.goodsQuality)
                CfUtils.SetUISwitchText(self.Text,self.data.merchant.goodsQuality)
                CfUtils.FillText(self.TxtNumber,self.data.merchant.goodsPrice)
            end
        end

    elseif self.type == TabType.Record then
        local isFriend = self.data.isFriend == 1
        local state = isFriend and 2 or 1
        CfUtils.SetUISwitchImage(self.RelationalTag,state)
        CfUtils.SetUISwitchText(self.RelationalTagTxt,state)

        local date = timestamp_to_time(self.data.timestamp)
        CfUtils.FillText(self.TxtTime,os.date(localize("_year_年_month_月_day_日 _hour_:_min_",{_year_ = date.year, _month_ = date.month,_day_ = date.day,_hour_= date.hour,_min_ = date.min})))
        CfUtils.FillText(self.TxtState,self.data.content)
        KTool.SetActive(self.FontStyleButton2.gameObject,not isFriend)

        if not isFriend then
            local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local isApply = maidCoffeeComponent:IsHaveApply(self.data.friendId)
            if isApply then
                self.FontStyleButton2.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B18",localize("已申请"))
            else
                self.FontStyleButton2.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B7",localize("申请好友"))
            end
        end

    end

    self:PlayShowAni()
end

function OverseaManageMerchantFriendCell:PlayShowAni()
    CfUtils.PlayAnimator(self.controller.gameObject,"Go")
end

function OverseaManageMerchantFriendCell:SetCommonShow()
    self.playerHeadEnv_:FreshAvatarFrame(self.data.avatar, self.data.avatarFrame)
    CfUtils.FillText(self.TxtLevel, string.format("Lv. %s",self.data.level))
    CfUtils.FillText(self.TxtPlayerName,self.data.name)
end

function OverseaManageMerchantFriendCell:IsNotOpen()
    return self.data.visitPermission == MaidCoffeeConstants.VisitPermission.NotOpen
end

function OverseaManageMerchantFriendCell:OnBtnCallOnClick()
    local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
    MaidCoffeeUtils.MaidCoffeeVisit(self.data.friendId)
end

function OverseaManageMerchantFriendCell:OnBtnApplyFriendClick()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isApply = maidCoffeeComponent:IsHaveApply(self.data.friendId)
    if isApply then
        GameUtils.Toast(localize("已申请好友，请等待"))
        return
    end

    local friendComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FriendComponent)
    friendComponent:AddFriend(self.data.friendId, function ()
        maidCoffeeComponent:SaveApplyFriendData(self.data.friendId)
        self.FontStyleButton2.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B7",localize("申请好友"))
    end)
end


function OverseaManageMerchantFriendCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageMerchantFriendCell